            raise TypeError("n must be an integer")
        if not isinstance(rules, list):
            raise TypeError("rules must be a list of tuples")
        # Build mapping from digit to list of possible replacements
        mapping = {}
        for rule in rules:
            if (
                not isinstance(rule, tuple)
                or len(rule) != 2
                or not all(isinstance(x, int) for x in rule)
                or not (0 <= rule[0] <= 9 and 0 <= rule[1] <= 9)
            ):
                raise ValueError("Each rule must be a tuple of two integers in the range 0-9")
            mapping.setdefault(rule[0], []).append(rule[1])

        from collections import deque

        visited = {n}
